class PseudoHuberLoss(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.c = 0.00054 * (dim ** 0.5)
        self.c_2 = self.c * self.c
    def forward(self, pred, targets):
        return torch.mean(torch.sqrt(torch.square(pred - targets) + self.c_2) - self.c)

criteria = PseudoHuberLoss(dim=3 * 64 * 64)
